<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue';
import type {PcApi} from '../api';
import type {OrderView} from '@quote/contracts';
import {fetchPrivateSource} from '../source-files';
import {SourceOperations,fileMeta,type SourceFile,type SourceReference,type SpreadsheetFieldMapping} from '../../../../packages/source-client/src';
import {createIndexedDbAssets} from '../../../../packages/source-client/src/assets';
import {SourceController,createSourceState} from '../../../../packages/source-client/src/controller';
const props=defineProps<{api:Pick<PcApi,'get'|'post'|'write'>;reference:SourceReference;userId:string;readonly?:boolean;locked?:boolean;mode?:'image'|'excel';orderVersion?:number}>(),emit=defineEmits<{(e:'changed'):void;(e:'busy-changed',v:boolean):void;(e:'failure',v:unknown):void}>();
const state=reactive(createSourceState()),input=ref<HTMLInputElement|null>(null),previewUrl=ref(''),previewName=ref(''),previewBusy=ref(false),error=ref(''),parentFileId=ref<string|undefined>(),initialized=ref(false);let controller:SourceController<Blob>|null=null,epoch=0;
const locked=computed(()=>!!props.locked||state.busy||previewBusy.value||!!state.pending),accept=computed(()=>props.reference.kind==='template'||props.mode==='image'?'.jpg,.jpeg,.png':props.reference.kind==='manufacturer'||props.mode==='excel'?'.xlsx,.xls,.csv':'.jpg,.jpeg,.png,.xlsx,.xls,.csv'),fields:{key:keyof SpreadsheetFieldMapping['columns'];label:string;required?:boolean}[]=[{key:'name',label:'品名',required:true},{key:'quantity',label:'数量',required:true},{key:'spec',label:'规格'},{key:'unit',label:'单位'},{key:'remark',label:'备注'},{key:'sourcePrice',label:'来源参考价'}];
const maxColumns=computed(()=>Math.max(1,...(state.job?.rawRows||[]).map(r=>r.cells.length))),parseAllowed=(f:SourceFile)=>['purchase_image','purchase_excel','manufacturer_source'].includes(f.purpose),isImage=(f:SourceFile)=>['jpg','jpeg','png'].includes(f.fileType);
function closePreview(){if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value='';previewName.value='';}
function failure(e:unknown){error.value=e instanceof Error?e.message:'原文件读取失败，请重试。';if([401,403,404,410].includes((e as {status?:number})?.status||0)){closePreview();state.files=[];state.job=null;state.preview=null;}emit('failure',e);}
async function version(){let value=props.orderVersion;if(value===undefined){if(props.reference.kind!=='purchase_revision')throw new Error('当前资料不属于采购草稿。');value=(await props.api.get<Pick<OrderView,'version'>>('/sales/purchase-orders/'+props.reference.orderId)).version;}if(!Number.isSafeInteger(value)||value<=0)throw new Error('当前订单版本无效，请重新加载采购草稿。');return value;}
function setup(){epoch++;controller?.dispose();closePreview();previewBusy.value=false;error.value='';initialized.value=false;try{const currentEpoch=epoch,userId=props.userId,reference=JSON.stringify(props.reference),api=props.api;const current=()=>currentEpoch===epoch&&props.userId===userId&&JSON.stringify(props.reference)===reference&&props.api===api;const operations=new SourceOperations<Blob>(userId,p=>props.api.get(p),(p,b,k)=>props.api.post(p,b,k),localStorage,createIndexedDbAssets(),undefined,current);controller=new SourceController(props.reference,p=>props.api.get(p),(p,b)=>props.api.post(p,b),operations,localStorage,state,{readonly:()=>!!props.readonly||!!props.locked,version,changed:()=>emit('changed'),busy:v=>emit('busy-changed',v||previewBusy.value),failure});initialized.value=true;void controller.refresh();}catch(e){controller=null;failure(e);}}
watch(()=>JSON.stringify([props.reference,props.userId]),setup,{immediate:true});
async function selectFiles(e:Event){const selected=Object.freeze(Array.from((e.target as HTMLInputElement).files||[]));if(input.value)input.value.value='';if(props.readonly||locked.value||!controller)return;const originalController=controller,currentEpoch=epoch,reference=Object.freeze({...props.reference}),userId=props.userId,parent=parentFileId.value;const current=()=>currentEpoch===epoch&&controller===originalController&&props.userId===userId&&JSON.stringify(props.reference)===JSON.stringify(reference);for(const f of selected){if(!current())return;try{fileMeta(f.name,f.size,reference);await originalController.upload({name:f.name,mime:f.type,size:f.size},f,parent);if(!current())return;if(state.error||state.pending)break;}catch(e){if(current())failure(e);break;}}if(current())parentFileId.value=undefined;}
function choose(parent?:SourceFile){if(props.readonly||locked.value)return;parentFileId.value=parent?.id;input.value?.click();}
async function openFile(file:SourceFile,download=false){if(locked.value)return;const currentEpoch=epoch;previewBusy.value=true;error.value='';emit('busy-changed',true);try{const ticket=await props.api.post<{url:string;expiresAt:string}>('/files/'+encodeURIComponent(file.id)+'/download-url',{});const blob=await fetchPrivateSource(ticket.url);if(currentEpoch!==epoch)return;const url=URL.createObjectURL(blob);if(!download&&isImage(file)){closePreview();previewUrl.value=url;previewName.value=file.fileName;}else{const a=document.createElement('a');a.href=url;a.download=file.fileName;a.rel='noopener';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}}catch(e){if(currentEpoch===epoch)failure(e);}finally{if(currentEpoch===epoch){previewBusy.value=false;emit('busy-changed',!!state.pending);}}}
function setHeader(e:Event){controller?.invalidatePreview();state.mapping.headerRow=Number((e.target as HTMLInputElement).value);}
function column(field:keyof SpreadsheetFieldMapping['columns'],e:Event){controller?.setColumn(field,(e.target as HTMLSelectElement).value);}
function refresh(){return controller?.refresh();}
defineExpose({refresh,canLeave:()=>!previewBusy.value&&(controller?.canLeave()??true),pendingTarget:()=>state.pending?.reference||null,parsedJob:computed(()=>state.job?Object.freeze({...state.job}):null),sourceFiles:computed(()=>Object.freeze(state.files.map(f=>Object.freeze({...f,reference:Object.freeze({...f.reference})})))),check:()=>controller?.check(),retry:()=>controller?.retryPending()});
onBeforeUnmount(()=>{epoch++;controller?.dispose();closePreview();emit('busy-changed',false);});
</script>
<template>
 <section class="source-files" aria-label="原始资料">
  <div class="source-heading"><div><h3>原始资料</h3><p>单文件不超过 20MB；采购图片每单最多 20 张。原文件与修改后的候选分别保留。</p></div><button :disabled="locked||!initialized" @click="refresh">刷新</button></div>
  <p v-if="readonly" class="source-note">当前资料只读，可查看原图和下载原文件。</p>
  <template v-else><input ref="input" class="file-picker" type="file" :accept="accept" multiple :disabled="locked" @change="selectFiles"/><button :disabled="locked||!initialized" @click="choose()">{{mode==='image'?'上传采购图片':mode==='excel'?'上传 Excel / CSV':'上传原始资料'}}</button><p class="source-note">jpg / png / xlsx / xls / csv。表格只读取第一张工作表，最多 1000 数据行、64 列；不执行公式、宏或外部链接。</p></template>
  <div v-if="state.pending" class="source-warning" role="status"><strong>上次原单操作结果待核实</strong><p>{{state.pending.action==='upload'?state.pending.body.fileName:'解析或候选应用'}} · 原文件和原请求已保留。先核对结果；未查到时可按原输入手动重试。</p><button :disabled="state.busy||previewBusy" @click="controller?.check()">核对原操作结果</button><button :disabled="state.busy||previewBusy" @click="controller?.retryPending()">使用原请求重试</button></div>
  <p v-if="state.error||error" class="source-error" role="alert">{{state.error||error}}</p><p v-if="state.notice" class="source-note" role="status">{{state.notice}}</p><p v-if="state.busy||previewBusy" class="source-note">正在处理，请稍候…</p>
  <div v-for="f in state.files" :key="f.id" class="source-file"><div><strong>{{f.fileName}}</strong><small>{{(f.byteSize/1024).toFixed(1)}} KB · {{f.createdAt.slice(0,16).replace('T',' ')}}{{f.parentFileId?' · 更正版（原件保留）':''}}</small></div><div class="source-actions"><button :disabled="locked" @click="openFile(f)">{{isImage(f)?'查看原图':'下载原表'}}</button><button v-if="isImage(f)" :disabled="locked" @click="openFile(f,true)">下载</button><button :disabled="locked" @click="controller?.openJob(f)">解析记录</button><template v-if="!readonly"><button v-if="parseAllowed(f)" :disabled="locked" @click="controller?.parse(f)">{{isImage(f)?'识别表格':'解析表格'}}</button><button :disabled="locked" @click="choose(f)">上传更正版</button></template></div></div>
  <p v-if="!state.files.length&&!state.busy" class="source-note">暂无原始资料。</p>
  <div v-if="previewUrl" class="source-original"><div class="source-heading"><strong>{{previewName}}</strong><button @click="closePreview">收起原图</button></div><img :src="previewUrl" :alt="previewName"/></div>
  <section v-if="state.job" class="parse-panel"><div class="source-heading"><h3>解析校对</h3><button :disabled="locked" @click="controller?.refreshJob()">刷新解析状态</button></div><p>状态：{{({pending:'等待解析',processing:'解析中',succeeded:'解析完成，待人工校对',failed:'解析失败'})[state.job.status]}} · 已尝试 {{state.job.attempts}} 次</p><p class="source-note">{{state.job.parserType==='ocr'?`识别置信度：${state.job.confidence===null?'未知':(state.job.confidence*100).toFixed(1)+'%'}`:'表格字段需人工映射。'}}；解析候选不会自动勾选、冻结或进入正式统计。</p>
   <div v-if="state.job.status==='failed'" class="source-warning"><strong>{{state.job.errorCode}}</strong><p>{{state.job.errorMessage}}。原文件仍可查看；也可返回采购明细手工录入。</p><template v-if="!readonly&&state.job.retryable"><label v-if="state.job.resultUnknown" class="source-ack"><input v-model="state.unknownAcknowledged" type="checkbox" :disabled="locked"/>我已人工核对上次识别结果未知，明确要求再次识别</label><button :disabled="locked||state.job.resultUnknown&&!state.unknownAcknowledged" @click="controller?.retryJob()">手动重试解析</button></template></div>
   <template v-if="state.job.rawRows"><h4>原始单元格</h4><div class="source-scroll"><table><thead><tr><th>原行号</th><th v-for="col in maxColumns" :key="col">第 {{col}} 列</th><th>原文问题</th></tr></thead><tbody><tr v-for="row in state.job.rawRows" :key="row.rowNumber"><td>{{row.rowNumber}}</td><td v-for="col in maxColumns" :key="col">{{row.cells[col-1]||'—'}}</td><td class="source-error">{{row.errors.join('；')}}</td></tr></tbody></table></div>
    <template v-if="reference.kind!=='manufacturer'"><div class="mapping"><label>表头行号（0 表示无表头）<input type="number" :value="state.mapping.headerRow" min="0" max="1001" :disabled="locked" @change="setHeader"/></label><label v-for="field in fields" :key="field.key">{{field.label}}{{field.required?' *':''}}<select :value="state.mapping.columns[field.key]??''" :disabled="locked" @change="column(field.key,$event)"><option v-if="!field.required" value="">{{field.key==='unit'?'未映射，按 kg 校对':'不使用'}}</option><option v-for="n in maxColumns" :key="n" :value="n-1">第 {{n}} 列</option></select></label></div><button :disabled="locked" @click="controller?.preview()">预览字段映射</button></template>
   </template>
   <template v-if="state.preview"><p>有效 {{state.preview.validRows}} 行 / 有问题 {{state.preview.invalidRows}} 行。单位须为 kg；来源参考价仅供查询。</p><div class="source-scroll"><table><thead><tr><th v-if="!readonly&&reference.kind==='purchase_revision'">选择</th><th>原行</th><th>品名 / 规格</th><th>数量 / 单位</th><th>备注 / 来源参考价</th><th>待处理问题</th></tr></thead><tbody><tr v-for="row in state.preview.rows" :key="row.rowNumber"><td v-if="!readonly&&reference.kind==='purchase_revision'"><input type="checkbox" :checked="state.selectedRows.includes(row.rowNumber)" :disabled="locked||!!row.errors.length||state.job.applied" @change="controller?.toggleRow(row.rowNumber,($event.target as HTMLInputElement).checked)"/></td><td>{{row.rowNumber}}</td><td>{{row.name}}<small>{{row.spec}}</small></td><td>{{row.quantity||'无效'}} {{row.unit}}</td><td>{{row.remark||'—'}}<small>{{row.sourcePrice||'—'}}</small></td><td class="source-error">{{row.errors.join('；')||'待人工核对'}}</td></tr></tbody></table></div><template v-if="!readonly&&reference.kind==='purchase_revision'"><p class="source-note">选中行仅追加到当前采购草稿，仍需逐行校对。原有明细保留，最多合计 200 行。</p><button :disabled="locked||!state.selectedRows.length||state.job.applied" @click="controller?.apply()">{{state.job.applied?'已加入采购草稿':`将选中 ${state.selectedRows.length} 行加入待校对草稿`}}</button></template></template>
  </section>
 </section>
</template>
<style scoped>
.source-files{min-width:0;color:#263c32}.source-heading{display:flex;align-items:start;justify-content:space-between;gap:16px}.source-heading h3{margin:0 0 7px;font-size:16px}.source-heading p,.source-note,small{font-size:12px;color:#6b7b71;line-height:1.7}small{display:block}.file-picker{display:none}.source-note{margin:10px 0}.source-file{padding:14px 0;border-bottom:1px solid #e0e7df;display:flex;justify-content:space-between;gap:16px;align-items:center}.source-file strong{overflow-wrap:anywhere;font-size:13px}.source-actions{display:flex;gap:7px;flex-wrap:wrap}.source-files button{font:inherit;font-size:12px;border:1px solid #cddacf;border-radius:5px;background:white;padding:7px 10px;color:#245741;cursor:pointer}.source-files button:disabled{opacity:.48;cursor:default}.source-warning{background:#fff7e7;border:1px solid #e6d1a6;border-radius:5px;padding:13px;margin:14px 0;font-size:13px}.source-warning button{margin-right:8px}.source-warning p{line-height:1.7}.source-error{color:#a04233!important;line-height:1.6;font-size:12px}.source-original{background:#f4f6f1;padding:15px;margin-top:18px}.source-original img{display:block;max-width:100%;height:auto;margin:16px auto;max-height:680px;object-fit:contain}.parse-panel{border-top:1px solid #dfe5dd;margin-top:22px;padding-top:20px;font-size:13px}.source-scroll{max-height:390px;overflow:auto;margin:12px 0;border:1px solid #dce4db}.source-scroll table{border-collapse:collapse;min-width:100%;font-size:12px;white-space:pre-wrap}.source-scroll th,.source-scroll td{min-width:100px;max-width:230px;overflow-wrap:anywhere;text-align:left;padding:10px;border-bottom:1px solid #e4e9e1;vertical-align:top}.source-scroll th{background:#f1f5ef;position:sticky;top:0}.mapping{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin:18px 0}.mapping label{display:grid;gap:5px;font-size:12px}.mapping input,.mapping select{min-width:0;max-width:100%;padding:8px;border:1px solid #cad8ca;border-radius:4px;background:white}.source-ack{display:flex;align-items:start;gap:8px;margin:12px 0}@media(max-width:700px){.source-file{display:block}.source-actions{margin-top:10px}}
</style>
